const PROJECT_URL='https://weklmapqizeldfdalbgs.supabase.co';
async function req(path,{method='GET',body,key,token=key,headers={}}={}){const o={method,headers:{apikey:key,Authorization:`Bearer ${token}`,'Content-Type':'application/json',...headers}};if(body!==undefined)o.body=JSON.stringify(body);const r=await fetch(PROJECT_URL+path,o);const text=await r.text();let data=null;try{data=text?JSON.parse(text):null}catch{data={message:text}}return{ok:r.ok,status:r.status,data}}
module.exports=async function handler(req,res){res.setHeader('Content-Type','application/json');res.setHeader('Cache-Control','no-store');const service=String(process.env.SUPABASE_SERVICE_ROLE_KEY||'').trim();const result={env_present:!!service,env_shape:service?(/^sb_secret_/.test(service)?'secret':service.split('.').length===3?'jwt':'unknown'):'missing',steps:{}};if(!service){res.status(503).end(JSON.stringify(result));return}try{const users=await req('/auth/v1/admin/users?page=1&per_page=5',{key:service,token:service});result.steps.auth_admin={ok:users.ok,status:users.status,error:users.ok?null:(users.data?.message||users.data?.error||'unknown')};const profiles=await req('/rest/v1/profiles?select=id,role,is_active&limit=1',{key:service,token:service});result.steps.profiles={ok:profiles.ok,status:profiles.status,error:profiles.ok?null:(profiles.data?.message||profiles.data?.error||profiles.data?.hint||'unknown')};res.status(users.ok&&profiles.ok?200:500).end(JSON.stringify(result))}catch(e){result.exception=String(e&&e.message||e);res.status(500).end(JSON.stringify(result))}};
